// === 取值：兼容多种接线方式 ===
// 情况A：上游直接给 msg.message / msg.title（字符串）
// 情况B：上游是 HA action 节点输出，msg.payload = {message,title,notification_id}
// 情况C：msg.payload 是 HA 响应对象，原始数据在 msg.data
function pick(v, depth) {
    if (v == null || depth > 4) return "";
    if (typeof v === "string") return v;
    if (typeof v === "number" || typeof v === "boolean") return String(v);
    if (Array.isArray(v)) {
        return v.map(x => pick(x, depth + 1)).filter(Boolean).join("\n");
    }
    if (typeof v === "object") {
        for (const k of ["message", "text", "content", "payload", "data"]) {
            if (k in v) {
                const s = pick(v[k], depth + 1);
                if (s) return s;
            }
        }
    }
    return "";
}
let text = "";
for (const cand of [msg.message, msg.payload, msg.data]) {
    text = pick(cand, 0);
    if (text) break;
}
let title = String(msg.title || (msg.payload && msg.payload.title) || (msg.data && msg.data.title) || "").trim();

// === 清洗：链接 / HTML / emoji（屏幕字库无这些字形） ===
const emojiRe = /[\u{1F000}-\u{1FAFF}\u{203C}\u{2049}\u{2190}-\u{21FF}\u{2300}-\u{23FF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{200D}\u{20E3}]/gu;
text = text
    .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")        // markdown 图片 ![alt](url)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")       // markdown 链接 [text](url) → text
    .replace(/<img[^>]*>/gi, " ")                    // HTML 图片
    .replace(/<a[^>]*>([\s\S]*?)<\/a>/gi, "$1")    // HTML 链接 → 文字
    .replace(/<[^>]+>/g, " ")                        // 其余 HTML 标签
    .replace(/https?:\/\/\S+/g, " ")               // 裸 URL
    .replace(emojiRe, "");
title = title.replace(emojiRe, "").replace(/\s+/g, " ").trim();

// === 整理换行：去行首空格，3 连换行压成 2 ===
text = text.split("\n").map(l => l.trim()).join("\n")
           .replace(/\n{3,}/g, "\n\n").trim();

if (!title && !text) return null;                    // 空消息直接丢弃
if (!title) title = "通知";
if (title.length > 24) title = title.slice(0, 24);

// === UTF-8 字节安全截断（设备端上限 480B，这里 460B 留余量）===
const MAXB = 460;                                   // 设备端 480B，留余量
const LIM  = MAXB - 3;                              // 给结尾"…"预留 3 字节
if (Buffer.byteLength(text, "utf8") > MAXB) {
    let cut = LIM;
    while (cut > 0 && Buffer.byteLength(text.slice(0, cut), "utf8") > LIM) cut--;
    const nl = text.lastIndexOf("\n", cut);          // 尽量回退到行边界，别把一句话砍半
    if (nl > MAXB * 0.5) cut = nl;
    text = text.slice(0, cut).trimEnd() + "…";
}

msg.payload = JSON.stringify({
    title: title,
    message: text,
    ts: Math.floor(Date.now() / 1000)                // Unix 秒，屏幕本地化显示
});
return msg;
